import json, re, sys, time
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen

BASE = 'http://localhost:8080'

def parse_json_bytes(data):
    try:
        return json.loads(data.decode('utf-8'))
    except Exception:
        return None

def wait_seconds(headers, body):
    for key in ('Retry-After', 'X-Retry-After', 'X-Wait-Seconds'):
        val = headers.get(key)
        if val:
            try:
                return max(0.0, float(val))
            except ValueError:
                pass
    obj = parse_json_bytes(body) if body else None
    if isinstance(obj, dict):
        for key in ('retry_after', 'retry_after_seconds', 'wait', 'wait_seconds', 'seconds'):
            val = obj.get(key)
            if isinstance(val, (int, float)):
                return max(0.0, float(val))
            if isinstance(val, str):
                m = re.search(r'\\d+(?:\\.\\d+)?', val)
                if m:
                    return float(m.group(0))
        for key in ('detail', 'message', 'error'):
            val = obj.get(key)
            if isinstance(val, str):
                m = re.search(r'(?:wait|retry|after)\\D+(\\d+(?:\\.\\d+)?)', val, re.I)
                if m:
                    return float(m.group(1))
    text = body.decode('utf-8', 'replace') if body else ''
    m = re.search(r'(?:wait|retry|after)\\D+(\\d+(?:\\.\\d+)?)', text, re.I)
    return float(m.group(1)) if m else 1.0

def request(path, method='GET', token=None):
    global token_value
    while True:
        headers = {'Accept': 'application/json'}
        if token is not None:
            headers['Authorization'] = 'Bearer ' + token
        req = Request(BASE + path, method=method, headers=headers)
        try:
            with urlopen(req, timeout=20) as resp:
                body = resp.read()
                return resp.status, dict(resp.headers.items()), body
        except HTTPError as e:
            body = e.read()
            status = e.code
            hdrs = dict(e.headers.items())
            if status in (401, 403) and token is not None:
                print(f'auth failure {status} on {path}; refreshing token', flush=True)
                token_value = get_token()
                token = [REDACTED_SECRET]
                continue
            if status == 429:
                delay = wait_seconds(hdrs, body)
                print(f'rate limited on {path}; waiting {delay:g}s', flush=True)
                time.sleep(delay)
                continue
            if status >= 500:
                print(f'server error {status} on {path}; retrying after 1s', flush=True)
                time.sleep(1)
                continue
            print(f'request failure {status} on {path}; retrying after 1s: {body[:200]"'!r}'"', flush=True)
            time.sleep(1)
        except (URLError, TimeoutError, OSError) as e:
            print(f'transient error on {path}: {e}; retrying after 1s', flush=True)
            time.sleep(1)

def get_token():
    while True:
        status, _, body = request('/token', method='POST', token=None)
        obj = json.loads(body)
        tok = obj.get('token')
        if tok:
            return tok
        print('token response missing token; retrying', flush=True)
        time.sleep(1)

token_value = get_token()
print('token acquired', flush=True)

seen = set()
duplicate_count = 0
all_orders = []
total_pages = None
page = 1
while True:
    status, _, body = request(f'/orders?page={page}', token=[REDACTED_SECRET]
    payload = json.loads(body)
    if total_pages is None:
        total_pages = int(payload['total_pages'])
        print(f'orders report {total_pages} pages', flush=True)
    if int(payload.get('page', page)) "'!= page:
        raise RuntimeError(f'"'wrong page returned: requested {page}, got {payload.get(\"page\")}')
    items = payload.get('items', [])
    for order in items:
        oid = order['id']
        if oid in seen:
            duplicate_count += 1
        else:
            seen.add(oid)
            all_orders.append(order)
    print(f'page {page}/{total_pages}: {len(items)} listings, {len(seen)} unique', flush=True)
    nxt = payload.get('next')
    if page >= total_pages:
        if nxt is not None:
            print(f'warning: final page has next={nxt"'!r}'"', flush=True)
        break
    page += 1

start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end = datetime(2025, 6, 1, tzinfo=timezone.utc)
qualifying = []
for order in all_orders:
    if order.get('status') "'!= '"'shipped':
        continue
    placed = datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00')).astimezone(timezone.utc)
    if start <= placed < end:
        qualifying.append(order)

print(f'listed={len(all_orders)+duplicate_count} unique={len(all_orders)} duplicates_skipped={duplicate_count}', flush=True)
print(f'qualifying shipped orders={len(qualifying)}', flush=True)

customers = {}
for idx, order in enumerate(qualifying, 1):
    cid = order['customer_id']
    if cid not in customers:
        status, _, body = request(f'/customers/{cid}', token=[REDACTED_SECRET]
        if status "'!= 200:
            raise RuntimeError(f'"'customer {cid} returned {status}')
        customers[cid] = json.loads(body)
    if idx % 25 == 0 or idx == len(qualifying):
        print(f'customer cache progress: {idx}/{len(qualifying)} qualifying orders, {len(customers)} customers', flush=True)

by_region = {r: 0 for r in ('north', 'south', 'east', 'west')}
raw_total = 0
for order in qualifying:
    customer = customers[order['customer_id']]
    amount = Decimal(order['amount_cents'])
    discount = Decimal(customer['discount_pct'])
    discounted = (amount * (Decimal(100) - discount) / Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    cents = int(discounted)
    by_region[customer['region']] += cents
    raw_total += cents

result = {
    'total_cents': raw_total,
    'order_count': len(qualifying),
    'duplicates_skipped': duplicate_count,
    'by_region': by_region,
}
print('RESULT=' + json.dumps(result, sort_keys=True), flush=True)
PY"

